import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class SecureCode {

    /**
     * Executes a system command safely by passing arguments as separate elements.
     * This prevents Command Injection because the input is treated as data, not executable code.
     */
    public static void executeSystemCommandSafely(String host) {
        try {
            // Define the command and its arguments as separate elements in an array.
            // The operating system will treat 'host' strictly as an argument to 'ping', not as shell code.
            String[] command = {"ping", "-c", "1", host};

            System.out.println("Executing command safely with arguments: " + Arrays.toString(command));

            // Passing the array directly to exec() is the secure way to handle external commands.
            Process process = Runtime.getRuntime().exec(command);

            // Read the output of the process
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println("Output: " + line);
            }

            process.waitFor(); // Wait for the process to complete
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        // Example usage: If the input was "8.8.8.8; rm -rf /", 
        // the secure version would attempt to ping a host literally named "8.8.8.8; rm -rf /", 
        // which fails harmlessly instead of executing the malicious command.
        executeSystemCommandSafely("8.8.8.8"); 
    }
}
